/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    InventTransOrigin   inventTransOrigin;

    while select forupdate inventTransOrigin where inventTransOrigin.ReferenceCategory == InventTransType::Sales
        || inventTransOrigin.ReferenceCategory == InventTransType::Purch
    {
        ttsbegin;
        if (inventTransOrigin.referenceCategory == InventTransType::Sales)
        {
            InventTransOrigin.AVACustVendReference = SalesTable::find(inventTransOrigin.ReferenceId).CustAccount;
        }
        if (inventTransOrigin.ReferenceCategory == InventTransType::Purch)
        {
            InventTransOrigin.AVACustVendReference = PurchTable::find(inventTransOrigin.ReferenceId).OrderAccount;
        }

        inventTransOrigin.update();
        ttscommit;
    }

}
